BEGIN;
GRANT USAGE ON SCHEMA public,auth TO authenticated,anon;
GRANT ALL ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO authenticated;
CREATE FUNCTION prep_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END; $$;
CREATE FUNCTION prep_reject(command text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS rejected: % (%)',label,SQLERRM; RETURN; END; RAISE EXCEPTION 'FAIL accepted: %',label; END; $$;
INSERT INTO auth.users(id,email) VALUES('b1000000-0000-4000-8000-000000000001','preparation-director@example.test'),('b1000000-0000-4000-8000-000000000002','preparation-client@example.test');
INSERT INTO staff_users(auth_id,nom,email,role,must_change_password) VALUES('b1000000-0000-4000-8000-000000000001','Direction test','preparation-director@example.test','directeur',false);
INSERT INTO auth.users(id,email) VALUES('b1000000-0000-4000-8000-000000000003','preparation-logistician@example.test');
INSERT INTO staff_users(id,auth_id,nom,email,role,must_change_password) VALUES('b1100000-0000-4000-8000-000000000003','b1000000-0000-4000-8000-000000000003','Logistique test','preparation-logistician@example.test','logisticien',false);
INSERT INTO staff_permissions(staff_id,perm_colis_preparer) VALUES('b1100000-0000-4000-8000-000000000003',false);
INSERT INTO clients(id,user_id,nom,prenom,cp,type) VALUES('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Client préparation','Maya','97400','particulier');
INSERT INTO colis(id,client_id,statut,nb_colis,dims_par_colis,trackings_detail,feu_vert) VALUES('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','en_preparation',1,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]','[{"number":"REC-1"}]','autorise');
UPDATE tarifs SET base=10,par_kg=5 WHERE destination_code='974';
UPDATE destinations SET tva=8.5 WHERE code='974';
INSERT INTO categories(id,label) VALUES('b4000000-0000-4000-8000-000000000001','Préparation test');
INSERT INTO taux_categories(categorie_id,destination_code,om,omr) VALUES('b4000000-0000-4000-8000-000000000001','974',10,2.5);
SELECT prep_assert(NOT has_function_privilege('anon','save_preparation_measurements(uuid,jsonb,timestamptz,integer)','EXECUTE'),'anonymous cannot save physical preparation');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',true);
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
SELECT prep_reject($q$SELECT save_preparation_measurements('b3000000-0000-4000-8000-000000000001','[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',now(),0)$q$,'client cannot set final measures');
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
SELECT prep_reject($q$UPDATE colis SET fin_l=50,fin_w=40,fin_h=30,fin_p=20 WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'logistician cannot bypass preparation permission through legacy measurement columns');
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
SELECT prep_reject($q$SELECT save_preparation_measurements('b3000000-0000-4000-8000-000000000001','[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]','2001-01-01',0)$q$,'stale open version rejected');
SELECT prep_reject($q$INSERT INTO colis(client_id,statut,final_packages,final_measurements_version) VALUES('b2000000-0000-4000-8000-000000000001','receptionne','[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',0)$q$,'reception cannot forge certified final packages at insert');
UPDATE colis SET archive=true WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_reject($q$SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',updated_at,preparation_composition_version) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'archived dossier cannot receive preparation measures');
UPDATE colis SET archive=false,produit_interdit=true WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_reject($q$SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',updated_at,preparation_composition_version) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'prohibited content blocks physical preparation');
UPDATE colis SET produit_interdit=false,feu_vert='en_attente' WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_reject($q$SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',updated_at,preparation_composition_version) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'preparation requires an explicit recorded customer agreement');
UPDATE colis SET feu_vert='autorise' WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT save_preparation_measurements(id,'[{"dimL":"40","dimW":"10","dimH":"10","poids":"1"},{"dimL":"10","dimW":"40","dimH":"10","poids":"1"}]',updated_at,preparation_composition_version) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT final_measurements_version=preparation_composition_version AND outgoing_parcel_count=2 AND fin_p=2 AND poids_facturable=2 AND devis_total IS NULL FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'measure-only save works without invoice and sums independent volumes');
UPDATE colis SET feu_vert='refuse' WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_reject($q$SELECT save_quote(id,'{}',updated_at) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'withdrawn customer agreement also blocks a quote based on previously confirmed measures');
UPDATE colis SET feu_vert='autorise' WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_reject($q$UPDATE colis SET final_measurements_version=999 WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'direct freshness forgery rejected');
RESET ROLE;
INSERT INTO factures(id,colis_id,vendeur,montant,fichier_url,valide,rejet_motif) VALUES('b5000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','Originale',100,'old.pdf',false,'Illisible');
INSERT INTO factures(id,colis_id,vendeur,montant,fichier_url,valide,replaces_facture_id) VALUES('b5000000-0000-4000-8000-000000000002','b3000000-0000-4000-8000-000000000001','Corrigée',100,'new.pdf',true,'b5000000-0000-4000-8000-000000000001');
INSERT INTO lignes(colis_id,facture_id,description,qte,prix_unitaire,categorie_id) VALUES
('b3000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','Ancien article',1,100,'b4000000-0000-4000-8000-000000000001'),
('b3000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000002','Article correct',1,100,'b4000000-0000-4000-8000-000000000001');
SELECT prep_reject($q$INSERT INTO factures(colis_id,vendeur,replaces_facture_id) VALUES('b3000000-0000-4000-8000-000000000001','Doublon','b5000000-0000-4000-8000-000000000001')$q$,'replacement cannot be attached twice');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
SELECT save_quote(id,'{"devisTransport":20,"devisOM":12,"devisOMR":3,"devisTVA":2.98,"devisTotal":37.98,"inputs":{"destination":{"code":"976"},"client":{"type":"pro"}},"amounts":{}}',updated_at) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT devis_total=37.98 AND (devis_snapshot->'amounts'->>'merchandiseValue')::numeric=100 AND jsonb_array_length(devis_snapshot->'inputs'->'finalPackages')=2 FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'SQL excludes rejected invoice articles and freezes both prepared physical units');
SELECT prep_assert((SELECT devis_snapshot->'inputs'->'destination'->>'code'='974' AND devis_snapshot->'inputs'->'client'->>'type'='particulier' AND devis_snapshot->'inputs'->'client'->>'nom'='Client préparation Maya' FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'commercial snapshot identity is canonical despite a forged caller destination/type');
UPDATE colis SET statut='devis_envoye',devis_brouillon=false WHERE id='b3000000-0000-4000-8000-000000000001';
RESET ROLE;
INSERT INTO factures(colis_id,vendeur,montant,fichier_url,valide) VALUES('b3000000-0000-4000-8000-000000000001','Pièce supplémentaire',10,'extra.pdf',false);
SELECT prep_assert((SELECT statut='en_preparation' AND devis_total IS NULL AND devis_brouillon AND payplug_payment_url IS NULL FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'document revision returns to preparation instead of empty payment state');
-- A paid contract remains frozen; an unpaid modern quote is invalidated on destination change.
UPDATE colis SET devis_total=37.98,devis_transport=20,devis_snapshot='{"inputs":{"destination":{"code":"974"}}}',devis_brouillon=false,statut='devis_envoye' WHERE id='b3000000-0000-4000-8000-000000000001';
INSERT INTO payment_intents(colis_id,quote_version,amount_cents,status) SELECT id,quote_version,3798,'pending' FROM colis WHERE id='b3000000-0000-4000-8000-000000000001';
UPDATE clients SET cp='97600' WHERE id='b2000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT statut='en_preparation' AND devis_total IS NULL AND devis_brouillon FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'new destination invalidates modern unpaid quote');
SELECT prep_assert((SELECT status='superseded' FROM payment_intents WHERE colis_id='b3000000-0000-4000-8000-000000000001'),'old payment intention is superseded on destination revision');
SELECT revert_colis(id,updated_at) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001';
UPDATE colis SET nb_colis=2,dims_par_colis='[{"dimL":40,"dimW":30,"dimH":20,"poids":3},{"dimL":50,"dimW":40,"dimH":30,"poids":20}]',trackings_detail='[{"number":"REC-1"},{"number":"REC-2"}]',feu_vert='en_attente',statut='mesure' WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT preparation_composition_version=1 AND final_measurements_version IS NULL AND outgoing_parcel_count IS NULL AND fin_p=2 FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'new carton keeps historical final measures but invalidates confirmation and outgoing count');
UPDATE colis SET statut='attente_feu_vert' WHERE id='b3000000-0000-4000-8000-000000000001';
UPDATE colis SET statut='autorise',feu_vert='autorise' WHERE id='b3000000-0000-4000-8000-000000000001';
UPDATE colis SET statut='en_preparation' WHERE id='b3000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT prep_reject($q$SELECT save_quote(id,'{}',updated_at) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'quote cannot reuse final measures from previous carton composition');
SELECT prep_reject($q$SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',updated_at,0) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'$q$,'stale composition rejected even with current timestamp');
SELECT save_preparation_measurements(id,'[{"dimL":40,"dimW":30,"dimH":20,"poids":3}]',updated_at,1) FROM colis WHERE id='b3000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT final_measurements_version=1 AND outgoing_parcel_count=1 FROM colis WHERE id='b3000000-0000-4000-8000-000000000001'),'explicit remeasurement confirms current composition');
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
SELECT prep_assert((SELECT jsonb_array_length(final_packages)=1 AND devis_total IS NULL FROM client_colis WHERE id='b3000000-0000-4000-8000-000000000001'),'client safe view exposes actual outgoing units without draft totals');
RESET ROLE;
UPDATE clients SET adresse_ligne1='Nouvelle rue test',adresse_ligne2='Bâtiment B' WHERE id='b2000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT adresse=adresse_ligne1 AND adresse='Nouvelle rue test' FROM clients WHERE id='b2000000-0000-4000-8000-000000000001'),'staff address line is mirrored into legacy label address');
UPDATE clients SET adresse='Autre rue test' WHERE id='b2000000-0000-4000-8000-000000000001';
SELECT prep_assert((SELECT adresse_ligne1=adresse AND adresse_ligne2='Bâtiment B' FROM clients WHERE id='b2000000-0000-4000-8000-000000000001'),'legacy address correction preserves complement and canonical address');
ROLLBACK;
